class Solution {
    public: vector<int> countPairs(int n,vector<vector<int>>& edges,vector<int>& queries){
        vector<int> degree(n);
        map<pair<int,int>,int> multiplicity;
        for(auto edge:edges){
            int a=edge[0]-1,b=edge[1]-1;
            if(a>b)swap(a,b);
            ++degree[a];
            ++degree[b];
            ++multiplicity[{
                a,b
            }];
        }
        auto sorted=degree;
        sort(sorted.begin(),sorted.end());
        vector<int> answer;
        for(int query:queries){
            int left=0,right=n-1,count=0;
            while(left<right)if(sorted[left]+sorted[right]>query){
                count+=right-left;
                --right;
            }else ++left;
            for(auto& [pair,times]:multiplicity){
                auto [a,b]=pair;
                int sum=degree[a]+degree[b];
                if(sum>query&&sum-times<=query)--count;
            }
            answer.push_back(count);
        }
        return answer;
    }
};
